package br.com.confirmacao.professional.api;import br.com.confirmacao.professional.domain.Professional;import java.time.Instant;import java.util.UUID;public record ProfessionalResponse(UUID id,String fullName,String email,String phone,String registrationNumber,String specialty,String displayName,String timezone,int defaultSessionMinutes,String defaultModality,boolean remindersEnabled,boolean active,Instant createdAt,Instant updatedAt){public static ProfessionalResponse from(Professional p){return new ProfessionalResponse(p.getId(),p.getFullName(),p.getEmail(),p.getPhone(),p.getRegistrationNumber(),p.getSpecialty(),p.getDisplayName(),p.getTimezone(),p.getDefaultSessionMinutes(),p.getDefaultModality(),p.isRemindersEnabled(),p.isActive(),p.getCreatedAt(),p.getUpdatedAt());}}
